class="col-md-2"><label class="form-label">Tiết PPCT</label><input class="form-control" type="number" min="1" name="period" required></div><div class="col-md-4"><label class="form-label">Tên bài / nội dung</label><input class="form-control" name="title" required></div><div class="col-md-1"><button class="btn btn-primary">Lưu</button></div></form></section><?php endif;?><section class="lb-card"><div class="d-flex justify-content-between"><h2 class="h5">Danh mục PPCT<?=lb_is_admin()?'':' trong phạm vi được giao'?></h2><span class="badge text-bg-primary"><?=count($curriculumRows)?> dòng</span></div><div class="table-responsive"><table class="table table-hover"><thead><tr><th>Môn</th><th>Khối</th><th>Tiết</th><th>Tên bài</th><th>Ghi chú</th><th>Người cập nhật</th></tr></thead><tbody><?php $cur=$curriculumRows;usort($cur,fn($a,$b)=>strcmp(($a['subject'].'|'.$a['grade'].'|'.sprintf('%04d',$a['period'])),($b['subject'].'|'.$b['grade'].'|'.sprintf('%04d',$b['period']))));foreach($cur as$r):?><tr><td><?=e($r['subject'])?></td><td><?=e($r['grade'])?></td><td class="text-center"><?=e($r['period'])?></td><td><?=e($r['title'])?></td><td><?=e($r['note']??'')?></td><td><?=e($r['updated_by']??$r['created_by']??'')?></td></tr><?php endforeach;?></tbody></table></div></section>
