 <section class="lb-card"><h2 class="h5">Ảnh chữ ký giáo viên</h2><p>Ảnh được trình duyệt tự động cắt khoảng trắng, giữ đúng tỷ lệ và đặt trong khung PNG trong suốt 480 × 160 px; không phụ thuộc thư viện xử lý ảnh của máy chủ.</p><?php if($sig=lb_signature_meta()):?><div class="alert alert-success">Đã có chữ ký phiên bản <?=e($sig['version'])?>, tạo lúc <?=e($sig['created_at'])?>.</div><?php endif;?><form method="post" enctype="multipart/form-data" id="lbSignatureForm"><input type="hidden" name="csrf" value="<?=$csrf?>"><input type="hidden" name="action" value="upload_signature"><div class="input-group"><input class="form-control" type="file" name="signature" id="lbSignatureFile" accept="image/png,image/jpeg" required><button class="btn btn-primary" id="lbSignatureButton"><i class="bi bi-crop"></i> Chuẩn hóa và lưu</button></div><div class="form-text" id="lbSignatureStatus">Chọn ảnh PNG hoặc JPG có nét chữ ký rõ ràng.</div></form></section><script>(function(){const form=document.getElementById('lbSignatureForm'),input=document.getElementById('lbSignatureFile'),status=document.getElementById('lbSignatureStatus'),button=document.getElementById('lbSignatureButton');if(!form||!input)return;form.addEventListener('submit',async function(ev){if(form.dataset.ready==='1')return;ev.preventDefault();const file=input.files&&input.files[0];if(!file)return;button.disabled=true;status.textContent='Đang cắt và chuẩn hóa ảnh chữ ký…';try{const bitmap=await createImageBitmap(file),src=document.createElement('canvas');src.width=bitmap.width;src.height=bitmap.height;const ctx=src.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0);const data=ctx.getImageData(0,0,src.width,src.height),px=data.data;let minX=src.width,minY=src.height,maxX=-1,maxY=-1;for(let y=0;y<src.height;y++)for(let x=0;x<src.width;x++){const i=(y*src.width+x)*4;if(px[i+3]>15&&Math.min(px[i],px[i+1],px[i+2])<238){minX=Math.min(minX,x);maxX=Math.max(maxX,x);minY=Math.min(minY,y);maxY=Math.max(maxY,y)}}if(maxX<minX)throw new Error('Không nhận thấy nét chữ ký trong ảnh.');const out=document.createElement('canvas');out.width=480;out.height=160;const o=out.getContext('2d'),cw=maxX-minX+1,ch=maxY-minY+1,scale=Math.min(440/cw,120/ch),nw=Math.round(cw*scale),nh=Math.round(ch*scale);o.clearRect(0,0,480,160);o.drawImage(src,minX,minY,cw,ch,Math.round((480-nw)/2),Math.round((160-nh)/2),nw,nh);const blob=await new Promise(resolve=>out.toBlob(resolve,'image/png',1));if(!blob)throw new Error('Không tạo được ảnh PNG.');const transfer=new DataTransfer();transfer.items.add(new File([blob],'chu-ky-da-chuan-hoa.png',{type:'image/png'}));input.files=transfer.files;form.dataset.ready='1';status.textContent='Đã chuẩn hóa 480 × 160 px, đang lưu…';form.submit()}catch(err){button.disabled=false;status.textContent=err.message||'Không xử lý được ảnh chữ ký.'}})})();</script>
